{
  "model": "deepseek-v4-flash",
  "messages": [
    {
      "role": "system",
      "content": "Ты агент с инструментами нескольких MCP-серверов. Имя инструмента имеет вид \u003cсервер\u003e__\u003cинструмент\u003e; если описание или ошибка называет инструмент коротко, вызывай его с префиксом того же сервера. Сегодняшнюю дату ты не знаешь — узнай её инструментом. Если вопрос о сегодняшнем дне или о периоде относительно сегодня, сначала узнай дату и только потом вызывай инструменты, которым она нужна, передавая её явно; даты, названные в вопросе, бери из вопроса. Курсы валют бери только из инструментов, не из памяти. Вызывай только те инструменты, которые нужны для вопроса. Отвечай по-русски и коротко; если сохранил отчёт, назови имя файла; если какой-то шаг не удался, скажи об этом."
    },
    {
      "role": "user",
      "content": "Сколько сегодня стоят 1000 долларов в евро по курсу ЦБ и как менялся евро за последние 14 дней? Сохрани отчёт."
    }
  ],
  "stream": false,
  "temperature": 0,
  "thinking": {
    "type": "disabled"
  },
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "clock__current_date",
        "description": "Возвращает текущие дату, время и день недели по Москве (UTC+3).",
        "parameters": {
          "additionalProperties": false,
          "type": "object"
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "clock__shift_date",
        "description": "Сдвигает календарную дату на целое число дней. Для относительных периодов («неделю назад», «последние 14 дней») вызывайте этот инструмент вместо вычисления в уме. «Последние N дней» включают сегодняшний день: начало периода — сдвиг на −(N−1).",
        "parameters": {
          "additionalProperties": false,
          "properties": {
            "date": {
              "description": "Календарная дата в формате ГГГГ-ММ-ДД.",
              "type": "string"
            },
            "days": {
              "description": "Целое число календарных дней для сдвига; отрицательное число сдвигает назад.",
              "type": "integer"
            }
          },
          "required": [
            "date",
            "days"
          ],
          "type": "object"
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "rates__convert_currency",
        "description": "Конвертирует сумму по официальным курсам ЦБ РФ к рублю на дату ГГГГ-ММ-ДД; RUB разрешён, всегда берите курсы из этого инструмента, а не из памяти.",
        "parameters": {
          "additionalProperties": false,
          "properties": {
            "amount": {
              "description": "Сумма для конвертации, должна быть больше нуля.",
              "type": "number"
            },
            "date": {
              "description": "Дата курса в формате ГГГГ-ММ-ДД; если не указана, берётся последний курс.",
              "type": "string"
            },
            "from": {
              "description": "Исходная валюта ISO 4217 или RUB.",
              "type": "string"
            },
            "to": {
              "description": "Целевая валюта ISO 4217 или RUB.",
              "type": "string"
            }
          },
          "required": [
            "amount",
            "from",
            "to"
          ],
          "type": "object"
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "rates__get_currency_rates",
        "description": "Возвращает официальные курсы ЦБ РФ к рублю на дату ГГГГ-ММ-ДД; всегда берите курсы из этого инструмента, а не из памяти.",
        "parameters": {
          "additionalProperties": false,
          "properties": {
            "codes": {
              "description": "Коды валют ISO 4217; если не указаны или пусты, возвращаются все валюты.",
              "items": {
                "type": "string"
              },
              "type": [
                "null",
                "array"
              ]
            },
            "date": {
              "description": "Дата курса в формате ГГГГ-ММ-ДД; если не указана, берётся последний курс.",
              "type": "string"
            }
          },
          "type": "object"
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "pipeline__fetch_rates",
        "description": "Получить официальные публикации ЦБ одной валюты за период и сохранить датасет; первым шагом вызовите этот инструмент, затем передайте dataset_id в summarize_rates.",
        "parameters": {
          "additionalProperties": false,
          "properties": {
            "currency": {
              "description": "Буквенный код валюты ЦБ, например USD, EUR или CNY.",
              "type": "string"
            },
            "date_from": {
              "description": "Начало периода включительно в формате ГГГГ-ММ-ДД.",
              "type": "string"
            },
            "date_to": {
              "description": "Конец периода включительно в формате ГГГГ-ММ-ДД; период не длиннее 93 дней.",
              "type": "string"
            }
          },
          "required": [
            "currency",
            "date_from",
            "date_to"
          ],
          "type": "object"
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "pipeline__save_report",
        "description": "Сохранить проверяемый Markdown-отчёт по готовой сводке; передайте summary_id дословно из summarize_rates.",
        "parameters": {
          "additionalProperties": false,
          "properties": {
            "summary_id": {
              "description": "Идентификатор sm_…, дословно возвращённый summarize_rates.",
              "type": "string"
            }
          },
          "required": [
            "summary_id"
          ],
          "type": "object"
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "pipeline__summarize_rates",
        "description": "Посчитать детерминированную сводку сохранённого датасета; передайте dataset_id дословно из fetch_rates, затем передайте summary_id в save_report.",
        "parameters": {
          "additionalProperties": false,
          "properties": {
            "dataset_id": {
              "description": "Идентификатор ds_…, дословно возвращённый fetch_rates.",
              "type": "string"
            }
          },
          "required": [
            "dataset_id"
          ],
          "type": "object"
        }
      }
    }
  ]
}

